const input = $input.first().json;

// Validate and structure the research request
const researchRequest = {
  question: input.question || input.query || 'Default research question',
  context: input.context || '',
  depth: input.depth || 'comprehensive',
  sources: input.sources || ['academic', 'industry', 'news'],
  format: input.format || 'detailed_report',
  urgency: input.urgency || 'normal',
  requester: input.requester || 'anonymous',
  timestamp: new Date().toISOString(),
  request_id: `research_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
};

// Validate required fields
if (!researchRequest.question || researchRequest.question.length < 10) {
  throw new Error('Research question must be at least 10 characters long');
}

return researchRequest;

