const request = $node['Validate Research Input'].json;
const researchPlan = JSON.parse($node['AI Research Planner'].json.choices[0].message.content || '{}');
const researchContent = $node['AI Content Researcher'].json.choices[0].message.content;
const factCheck = JSON.parse($node['AI Fact Checker'].json.choices[0].message.content || '{}');

// Compile comprehensive research report
const researchReport = {
  request_info: {
    request_id: request.request_id,
    question: request.question,
    context: request.context,
    depth: request.depth,
    requester: request.requester,
    timestamp: request.timestamp,
    completion_time: new Date().toISOString()
  },

  research_plan: researchPlan,

  research_findings: {
    content: researchContent,
    word_count: researchContent.split(' ').length,
    sections_covered: [
      'Current State & Overview',
      'Expert Insights & Analysis', 
      'Case Studies & Examples',
      'Future Outlook',
      'Practical Applications'
    ]
  },

  quality_assessment: {
    fact_check_report: factCheck,
    confidence_score: factCheck.reliability_score || 8.5,
    verification_status: 'completed',
    bias_analysis: factCheck.bias_detection || 'No significant biases detected'
  },

  deliverables: {
    executive_summary: researchContent.substring(0, 500) + '...',
    full_report: researchContent,
    research_plan: researchPlan,
    fact_check: factCheck,
    next_steps: [
      'Review research findings',
      'Validate key sources independently',
      'Consider additional research if needed',
      'Apply insights to decision-making'
    ]
  },

  metadata: {
    research_depth: request.depth,
    sources_consulted: request.sources,
    processing_time_minutes: 5, // Estimated
    agent_version: '2.0',
    status: 'completed'
  }
};

return researchReport;

const report = $node['Compile Research Report'].json;
const stored = $node['Store Research Results'].json[0];

// Format user-friendly response
const response = {
  success: true,
  request_id: report.request_info.request_id,
  database_id: stored.id,

  summary: {
    question: report.request_info.question,
    confidence_score: report.quality_assessment.confidence_score,
    word_count: report.research_findings.word_count,
    status: 'Research completed successfully'
  },

  research_results: {
    executive_summary: report.deliverables.executive_summary,
    key_findings: report.research_findings.content.split('\n').slice(0, 5), // First 5 lines as key findings
    confidence_assessment: report.quality_assessment.fact_check_report
  },

  next_steps: report.deliverables.next_steps,

  access_info: {
    full_report_available: true,
    database_record: stored.id,
    research_plan_included: true,
    fact_check_completed: true
  },

  timestamp: new Date().toISOString()
};

return response;
